package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class AccountStore {
    private final Map<String, Account> accounts = new HashMap<>();
    private final Map<String, BigDecimal> usedToday = new HashMap<>();

    public void openAccount(String id, String tier, String currency, BigDecimal balance) {
        if (accounts.containsKey(id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        }
        accounts.put(id, new Account(id, tier, currency, balance));
    }

    public Account getAccount(String id) {
        return accounts.get(id);
    }

    public void addUsed(String id, String date, BigDecimal amount) {
        String key = id + "|" + date;
        BigDecimal current = usedToday.getOrDefault(key, BigDecimal.ZERO);
        usedToday.put(key, current.add(amount));
    }

    public BigDecimal getUsed(String id, String date) {
        return usedToday.getOrDefault(id + "|" + date, BigDecimal.ZERO);
    }
}

