package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

public class TransactionStore {
    private final Map<String, Transaction> txs = new LinkedHashMap<>();
    private final List<String> audit = new ArrayList<>();
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    private int auditSeq = 0;
    private int txSeq = 0;

    public String nextTxId() {
        return String.format("TX-%06d", ++txSeq);
    }

    public void addTransaction(String id, Transaction tx) {
        txs.put(id, tx);
    }

    public Transaction getTransaction(String id) {
        return txs.get(id);
    }

    public void addAudit(String verb, String date, String outcome) {
        auditSeq++;
        audit.add(String.format("%03d  %s %s %s", auditSeq, verb, date, outcome));
    }

    public void addCount(String date, int type) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[type]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        BigDecimal old = m.getOrDefault(currency, BigDecimal.ZERO);
        m.put(currency, old.add(delta));
    }

    public List<String> getAuditLog() {
        return new ArrayList<>(audit);
    }

    public String generateReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        String feeText = getFeeText(date);
        return String.format("REPORT %s\nok: %d\nrejected: %d\nfees: %s", date, ok, rejected, feeText);
    }

    private String getFeeText(String date) {
        Map<String, BigDecimal> f = fees.get(date);
        if (f == null || f.isEmpty()) return "none";
        List<String> parts = new ArrayList<>();
        for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
            parts.add(e.getValue() + " " + e.getKey());
        }
        return String.join(", ", parts);
    }
}

