package com.rustyledger;

import java.math.BigDecimal;

public class CommandParser {
    public Command parse(String line) {
        Command cmd = new Command();
        if (line == null || line.trim().isEmpty()) {
            return error(cmd, "???", "BAD_INSTRUCTION", "empty instruction");
        }
        String[] f = line.split("\\|", -1);
        cmd.verb = f[0];
        int want = getWant(cmd.verb);
        if (want == -1) return error(cmd, "???", "BAD_INSTRUCTION", "unknown verb " + cmd.verb);
        if (f.length != want) return error(cmd, cmd.verb, "BAD_INSTRUCTION", cmd.verb + " needs " + want + " fields");
        cmd.date = f[1];
        if (!cmd.date.matches("\\d{4}-\\d{2}-\\d{2}")) return error(cmd, cmd.verb, "BAD_DATE", cmd.date);
        if (cmd.verb.equals("REVERSE")) {
            cmd.txId = f[2];
            return cmd;
        }
        cmd.fromId = cmd.verb.equals("TRANSFER") ? f[2] : (cmd.verb.equals("WITHDRAW") ? f[2] : f[2]);
        cmd.toId = cmd.verb.equals("TRANSFER") ? f[3] : null;
        cmd.amount = (cmd.verb.equals("TRANSFER") ? f[4] : f[3]);
        cmd.currency = cmd.verb.equals("TRANSFER") ? f[5] : null;
        if (cmd.amount == null || !cmd.amount.matches("\\d+(\\.\\d{1,2})?")) {
            return error(cmd, cmd.verb, "BAD_AMOUNT", cmd.amount == null ? "" : cmd.amount);
        }
        try {
            BigDecimal amt = new BigDecimal(cmd.amount).setScale(2);
            if (amt.signum() <= 0) return error(cmd, cmd.verb, "BAD_AMOUNT", cmd.amount);
            cmd.amount = amt;
        } catch (Exception e) { return error(cmd, cmd.verb, "BAD_AMOUNT", cmd.amount); }
        return cmd;
    }

    private int getWant(String verb) {
        return switch (verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> -1;
        };
    }

    private Command error(Command cmd, String verb, String code, String msg) {
        cmd.verb = verb; cmd.errorCode = code; cmd.errorMessage = msg;
        return cmd;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeService {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if (tier.equals("STANDARD")) {
            return amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.20"));
        } else if (tier.equals("PREMIUM")) {
            return amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return BigDecimal.ZERO;
    }

    public BigDecimal calculateWithdrawFee(String tier) {
        return tier.equals("STANDARD") ? new BigDecimal("1.00") : BigDecimal.ZERO;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyService {
    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!tier.equals("STAFF")) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }

    private BigDecimal rate(String currency) {
        return switch (currency) {
            case "EUR" -> new BigDecimal("4.30");
            case "USD" -> new BigDecimal("4.00");
            default -> new BigDecimal("1.00");
        };
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.List;

public class LedgerImpl implements Ledger {
    private final AccountStore accounts = new AccountStore();
    private final TransactionStore txs = new TransactionStore();
    private final FeeService feeService = new FeeService();
    private final CurrencyService currencyService = new CurrencyService();
    private final CommandParser parser = new CommandParser();

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!List.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!List.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        accounts.openAccount(id, tier, currency, new BigDecimal(openingBalance));
    }

    public String balance(String id) {
        Account a = accounts.getAccount(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.getBalance() + " " + a.getCurrency();
    }

    public List<String> auditLog() { return txs.getAuditLog(); }

    public String dailyReport(String date) { return txs.generateReport(date); }

    public String submit(String line) {
        Command cmd = parser.parse(line);
        if (cmd.isError()) return reject(cmd);
        if (cmd.verb.equals("REVERSE")) return doReverse(cmd);
        if (cmd.verb.equals("TRANSFER")) return doTransfer(cmd);
        if (cmd.verb.equals("WITHDRAW")) return doWithdraw(cmd);
        return doDeposit(cmd);
    }

    private String reject(Command cmd) {
        if (cmd.date != null) txs.addCount(cmd.date, 1);
        txs.addAudit(cmd.verb, cmd.date == null ? "????-??-??" : cmd.date, "REJECTED " + cmd.errorCode);
        return "REJECTED " + cmd.errorCode + ": " + cmd.errorMessage;
    }

    private String doTransfer(Command cmd) {
        Account from = accounts.getAccount(cmd.fromId);
        Account to = accounts.getAccount(cmd.toId);
        String err = validateTransfer(cmd, from, to);
        if (err != null) return err;

        BigDecimal fee = feeService.calculateTransferFee(from.getTier(), cmd.amount);
        String fundErr = checkFunds(cmd, from, fee);
        if (fundErr != null) return fundErr;

        BigDecimal credited = cmd.currency.equals(to.getCurrency()) ? cmd.amount : currencyService.convert(cmd.amount, from.getCurrency(), to.getCurrency(), from.getTier());
        from.setBalance(from.getBalance().subtract(cmd.amount.add(fee)));
        to.setBalance(to.getBalance().add(credited));
        accounts.addUsed(from.getId(), cmd.date, cmd.amount);

        String txId = txs.nextTxId();
        txs.addTransaction(txId, new Transaction("TRANSFER", cmd.date, from.getId(), to.getId(), cmd.amount, from.getCurrency(), fee, credited));
        txs.addFee(cmd.date, from.getCurrency(), fee);
        txs.addCount(cmd.date, 0);
        txs.addAudit(cmd.verb, cmd.date, "OK " + txId);
        return "OK " + txId + " fee=" + fee + " " + from.getCurrency();
    }

    private String validateTransfer(Command cmd, Account from, Account to) {
        if (from == null) return rejectCmd(cmd, "TRANSFER", "UNKNOWN_ACCOUNT", cmd.fromId);
        if (to == null) return rejectCmd(cmd, "TRANSFER", "UNKNOWN_ACCOUNT", cmd.toId);
        if (cmd.fromId.equals(cmd.toId)) return rejectCmd(cmd, "TRANSFER", "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.getCurrency().equals(cmd.currency)) return rejectCmd(cmd, "TRANSFER", "CURRENCY_MISMATCH", from.getId() + " holds " + from.getCurrency());
        return null;
    }

    private String checkFunds(Command cmd, Account from, BigDecimal fee) {
        BigDecimal limit = from.getTier().equals("STANDARD") ? new BigDecimal("5000.00") : (from.getTier().equals("PREMIUM") ? new BigDecimal("20000.00") : new BigDecimal("50000.00"));
        if (accounts.getUsed(from.getId(), cmd.date).add(cmd.amount).compareTo(limit) > 0) 
            return rejectCmd(cmd, "TRANSFER", "LIMIT_EXCEEDED", "daily limit " + limit + " for " + from.getTier());
        BigDecimal needed = cmd.amount.add(fee);
        BigDecimal overdraft = from.getTier().equals("PREMIUM") ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (from.getBalance().subtract(needed).compareTo(overdraft.negate()) < 0)
            return rejectCmd(cmd, "TRANSFER", "INSUFFICIENT_FUNDS", "balance " + from.getBalance() + " " + from.getCurrency() + ", needed " + needed + " " + from.getCurrency());
        return null;
    }

    private String doWithdraw(Command cmd) {
        Account a = accounts.getAccount(cmd.fromId);
        if (a == null) return rejectCmd(cmd, "WITHDRAW", "UNKNOWN_ACCOUNT", cmd.fromId);
        BigDecimal fee = feeService.calculateWithdrawFee(a.getTier());
        BigDecimal limit = a.getTier().equals("STANDARD") ? new BigDecimal("5000.00") : (a.getTier().equals("PREMIUM") ? new BigDecimal("20000.00") : new BigDecimal("50000.00"));
        if (accounts.getUsed(a.getId(), cmd.date).add(cmd.amount).compareTo(limit) > 0)
            return rejectCmd(cmd, "WITHDRAW", "LIMIT_EXCEEDED", "daily limit " + limit + " for " + a.getTier());
        BigDecimal needed = cmd.amount.add(fee);
        if (a.getBalance().subtract(needed).compareTo(BigDecimal.ZERO) < 0)
            return rejectCmd(cmd, "WITHDRAW", "INSUFFICIENT_FUNDS", "balance " + a.getBalance() + " " + a.getCurrency() + ", needed " + needed + " " + a.getCurrency());

        a.setBalance(a.getBalance().subtract(needed));
        accounts.addUsed(a.getId(), cmd.date, cmd.amount);
        String txId = txs.nextTxId();
        txs.addTransaction(txId, new Transaction("WITHDRAW", cmd.date, a.getId(), "", cmd.amount, a.getCurrency(), fee, cmd.amount));
        txs.addFee(cmd.date, a.getCurrency(), fee);
        txs.addCount(cmd.date, 0);
        txs.addAudit(cmd.verb, cmd.date, "OK " + txId);
        return "OK " + txId + " fee=" + fee + " " + a.getCurrency();
    }

    private String doDeposit(Command cmd) {
        Account a = accounts.getAccount(cmd.fromId);
        if (a == null) return rejectCmd(cmd, "DEPOSIT", "UNKNOWN_ACCOUNT", cmd.fromId);
        a.setBalance(a.getBalance().add(cmd.amount));
        String txId = txs.nextTxId();
        txs.addTransaction(txId, new Transaction("DEPOSIT", cmd.date, a.getId(), "", cmd.amount, a.getCurrency(), BigDecimal.ZERO, cmd.amount));
        txs.addCount(cmd.date, 0);
        txs.addAudit(cmd.verb, cmd.date, "OK " + txId);
        return "OK " + txId + " fee=0.00 " + a.getCurrency();
    }

    private String doReverse(Command cmd) {
        Transaction tx = txs.getTransaction(cmd.txId);
        if (tx == null) return rejectCmd(cmd, "REVERSE", "UNKNOWN_TX", cmd.txId);
        if (!tx.verb.equals("TRANSFER")) return rejectCmd(cmd, "REVERSE", "NOT_REVERSIBLE", cmd.txId + " is a " + tx.verb);
        if (tx.isReversed) return rejectCmd(cmd, "REVERSE", "ALREADY_REVERSED", cmd.txId);
        if (!tx.date.equals(cmd.date)) return rejectCmd(cmd, "REVERSE", "REVERSAL_WINDOW", tx.date + " was made on " + tx.date);

        Account from = accounts.getAccount(tx.fromId);
        Account to = accounts.getAccount(tx.toId);
        to.setBalance(to.getBalance().subtract(tx.credited));
        BigDecimal back = tx.amount;
        if (from.getTier().equals("PREMIUM")) {
            back = back.add(tx.fee);
            if (tx.fee.signum() != 0) txs.addFee(cmd.date, from.getCurrency(), tx.fee.negate());
        }
        from.setBalance(from.getBalance().add(back));
        tx.isReversed = true;
        String newId = txs.nextTxId();
        txs.addTransaction(newId, new Transaction("REVERSE", cmd.date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited));
        txs.addCount(cmd.date, 0);
        txs.addAudit(cmd.verb, cmd.date, "OK " + newId + " reversed " + cmd.txId);
        return "OK " + newId + " reversed " + cmd.txId;
    }

    private String rejectCmd(Command cmd, String verb, String code, String msg) {
        txs.addCount(cmd.date, 1);
        txs.addAudit(verb, cmd.date == null ? "????-??-??" : cmd.date, "REJECTED " + code);
        return "REJECTED " + code + ": " + msg;
    }
}

